"use client";

import { useEffect, use } from 'react';

const pageStyle = "\n@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Mono:wght@400;500&family=DM+Sans:ital,wght@0,300;0,400;0,500;0,600;1,400&display=swap');\n\n:root {\n  --red: #E5000A;\n  --red2: #ff1a22;\n  --dark: #0A0A0A;\n  --dark2: #111111;\n  --dark3: #181818;\n  --cream: #F5F0E8;\n  --cream2: #EDE8DE;\n  --text: #1A1A1A;\n  --text-dim: #555;\n  --white: #FAFAF8;\n  --border: #2A2A2A;\n}\n\n*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  background: var(--cream);\n  color: var(--text);\n  font-family: 'DM Sans', sans-serif;\n  font-size: 14px;\n  line-height: 1.6;\n}\n\n/* ─── COVER ──────────────────────────────────────── */\n.cover {\n  background: var(--dark);\n  color: var(--cream);\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  position: relative;\n  overflow: hidden;\n  padding: 0;\n}\n\n.cover-grid {\n  position: absolute; inset: 0;\n  background-image:\n    linear-gradient(rgba(229,0,10,0.06) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(229,0,10,0.06) 1px, transparent 1px);\n  background-size: 48px 48px;\n}\n\n.cover-inner {\n  position: relative; z-index: 2;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n}\n\n.cover-header {\n  padding: 28px 52px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  border-bottom: 1px solid rgba(255,255,255,0.07);\n}\n\n.brand {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 28px;\n  letter-spacing: 4px;\n  color: var(--cream);\n}\n\n.brand span { color: var(--red); }\n\n.cover-tag {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  letter-spacing: 2px;\n  color: rgba(255,255,255,0.35);\n  text-transform: uppercase;\n}\n\n.cover-main {\n  flex: 1;\n  padding: 60px 52px 0;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n}\n\n.cover-eyebrow {\n  font-family: 'DM Mono', monospace;\n  font-size: 11px;\n  letter-spacing: 3px;\n  color: var(--red);\n  text-transform: uppercase;\n  margin-bottom: 20px;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.cover-eyebrow::before {\n  content: '';\n  display: inline-block;\n  width: 24px; height: 2px;\n  background: var(--red);\n}\n\n.cover-headline {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: clamp(72px, 12vw, 148px);\n  line-height: 0.9;\n  color: var(--cream);\n  letter-spacing: 2px;\n  max-width: 900px;\n}\n\n.cover-headline em {\n  color: var(--red);\n  font-style: normal;\n}\n\n.cover-sub {\n  margin-top: 32px;\n  font-size: 16px;\n  color: rgba(255,255,255,0.5);\n  font-weight: 300;\n  max-width: 520px;\n  line-height: 1.7;\n}\n\n.cover-pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  margin-top: 40px;\n}\n\n.pill {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  letter-spacing: 1.5px;\n  text-transform: uppercase;\n  padding: 7px 16px;\n  border: 1px solid rgba(255,255,255,0.15);\n  color: rgba(255,255,255,0.6);\n  border-radius: 2px;\n}\n\n.pill.accent {\n  border-color: var(--red);\n  color: var(--red);\n}\n\n.cover-stats {\n  display: flex;\n  gap: 0;\n  border-top: 1px solid rgba(255,255,255,0.07);\n  margin-top: auto;\n}\n\n.stat-block {\n  flex: 1;\n  padding: 28px 52px;\n  border-right: 1px solid rgba(255,255,255,0.07);\n}\n\n.stat-block:last-child { border-right: none; }\n\n.stat-num {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 42px;\n  color: var(--cream);\n  letter-spacing: 2px;\n  line-height: 1;\n}\n\n.stat-label {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 2px;\n  color: rgba(255,255,255,0.3);\n  text-transform: uppercase;\n  margin-top: 4px;\n}\n\n/* ─── PAGE WRAPPER ───────────────────────────────── */\n.page {\n  max-width: 960px;\n  margin: 0 auto;\n  padding: 0 40px;\n}\n\n/* ─── SECTION DIVIDERS ───────────────────────────── */\n.section {\n  padding: 80px 0;\n  border-bottom: 1px solid rgba(0,0,0,0.08);\n}\n\n.section:last-child { border-bottom: none; }\n\n.section-label {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  letter-spacing: 3px;\n  color: var(--red);\n  text-transform: uppercase;\n  margin-bottom: 10px;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.section-label::before {\n  content: '';\n  display: inline-block;\n  width: 16px; height: 1px;\n  background: var(--red);\n}\n\n.section-title {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: clamp(40px, 6vw, 72px);\n  line-height: 1;\n  color: var(--dark);\n  letter-spacing: 1px;\n  margin-bottom: 16px;\n}\n\n.section-body {\n  font-size: 15px;\n  color: #444;\n  max-width: 640px;\n  line-height: 1.75;\n}\n\n/* ─── ABOUT / INTRO SECTION ──────────────────────── */\n.intro-layout {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 64px;\n  align-items: start;\n  margin-top: 48px;\n}\n\n.intro-text {\n  font-size: 15px;\n  color: #3A3A3A;\n  line-height: 1.8;\n}\n\n.intro-text p + p { margin-top: 16px; }\n\n.differentiators {\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n}\n\n.diff-item {\n  padding: 20px 0;\n  border-bottom: 1px solid rgba(0,0,0,0.08);\n  display: flex;\n  gap: 16px;\n  align-items: flex-start;\n}\n\n.diff-item:first-child { border-top: 1px solid rgba(0,0,0,0.08); }\n\n.diff-num {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 28px;\n  color: var(--red);\n  line-height: 1;\n  min-width: 40px;\n}\n\n.diff-title {\n  font-weight: 600;\n  font-size: 14px;\n  margin-bottom: 4px;\n}\n\n.diff-text {\n  font-size: 13px;\n  color: #666;\n  line-height: 1.6;\n}\n\n/* ─── 4-WEEK STRUCTURE ───────────────────────────── */\n.weeks-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 2px;\n  margin-top: 48px;\n  background: rgba(0,0,0,0.06);\n  border: 1px solid rgba(0,0,0,0.08);\n}\n\n.week-card {\n  background: var(--white);\n  padding: 32px 28px;\n  position: relative;\n  overflow: hidden;\n}\n\n.week-card::before {\n  content: '';\n  position: absolute;\n  top: 0; left: 0;\n  width: 3px; height: 100%;\n  background: var(--red);\n  transform: scaleY(0);\n  transform-origin: top;\n  transition: transform 0.3s ease;\n}\n\n.week-card:hover::before { transform: scaleY(1); }\n\n.week-badge {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 64px;\n  color: rgba(229,0,10,0.08);\n  position: absolute;\n  bottom: -12px; right: 16px;\n  line-height: 1;\n  pointer-events: none;\n}\n\n.week-label {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 2px;\n  text-transform: uppercase;\n  color: var(--red);\n  margin-bottom: 8px;\n}\n\n.week-title {\n  font-size: 17px;\n  font-weight: 600;\n  color: var(--dark);\n  margin-bottom: 10px;\n}\n\n.week-desc {\n  font-size: 13px;\n  color: #555;\n  line-height: 1.65;\n  margin-bottom: 14px;\n}\n\n.milestone {\n  font-family: 'DM Mono', monospace;\n  font-size: 11px;\n  color: var(--dark);\n  background: rgba(229,0,10,0.06);\n  border: 1px solid rgba(229,0,10,0.15);\n  padding: 8px 12px;\n  border-radius: 2px;\n  position: relative;\n  z-index: 1;\n}\n\n.milestone::before {\n  content: '✓ ';\n  color: var(--red);\n}\n\n/* ─── TRACKS ─────────────────────────────────────── */\n.tracks-nav {\n  display: flex;\n  gap: 0;\n  margin: 48px 0 0;\n  border: 1px solid rgba(0,0,0,0.1);\n  overflow: hidden;\n}\n\n.track-tab {\n  flex: 1;\n  padding: 16px 8px;\n  background: var(--white);\n  border: none;\n  border-right: 1px solid rgba(0,0,0,0.08);\n  cursor: pointer;\n  text-align: center;\n  transition: all 0.2s;\n}\n\n.track-tab:last-child { border-right: none; }\n\n.track-tab.active {\n  background: var(--dark);\n  color: var(--cream);\n}\n\n.track-tab:hover:not(.active) { background: var(--cream2); }\n\n.track-icon {\n  font-size: 20px;\n  display: block;\n  margin-bottom: 4px;\n}\n\n.track-name {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 1.5px;\n  text-transform: uppercase;\n  display: block;\n}\n\n.track-panels { margin-top: 2px; }\n\n.track-panel { display: none; }\n.track-panel.active { display: block; }\n\n.track-header {\n  background: var(--dark);\n  color: var(--cream);\n  padding: 36px 40px;\n  display: flex;\n  align-items: flex-start;\n  gap: 32px;\n}\n\n.track-hero-num {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 80px;\n  color: rgba(255,255,255,0.06);\n  line-height: 1;\n  min-width: 100px;\n}\n\n.track-hero-content {}\n\n.track-hero-label {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  letter-spacing: 2px;\n  color: var(--red);\n  text-transform: uppercase;\n  margin-bottom: 8px;\n}\n\n.track-hero-title {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 42px;\n  letter-spacing: 1px;\n  line-height: 1;\n  margin-bottom: 12px;\n}\n\n.track-hero-desc {\n  font-size: 14px;\n  color: rgba(255,255,255,0.5);\n  max-width: 560px;\n  line-height: 1.7;\n}\n\n.projects-table {\n  width: 100%;\n  border-collapse: collapse;\n  background: var(--white);\n}\n\n.projects-table thead tr {\n  background: var(--cream2);\n}\n\n.projects-table th {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 1.5px;\n  text-transform: uppercase;\n  color: #666;\n  padding: 12px 16px;\n  text-align: left;\n  border-bottom: 2px solid rgba(0,0,0,0.08);\n}\n\n.projects-table td {\n  padding: 13px 16px;\n  border-bottom: 1px solid rgba(0,0,0,0.05);\n  font-size: 13px;\n  vertical-align: top;\n}\n\n.projects-table tr:last-child td { border-bottom: none; }\n\n.projects-table tr:hover td { background: rgba(229,0,10,0.02); }\n\n.proj-num {\n  font-family: 'DM Mono', monospace;\n  font-size: 11px;\n  color: var(--red);\n  min-width: 28px;\n}\n\n.proj-name {\n  font-weight: 600;\n  color: var(--dark);\n  line-height: 1.4;\n}\n\n.proj-desc {\n  font-size: 12px;\n  color: #666;\n  margin-top: 3px;\n  line-height: 1.5;\n}\n\n.proj-tools {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  color: #777;\n  line-height: 1.6;\n}\n\n.level-badge {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 1px;\n  padding: 3px 8px;\n  border-radius: 2px;\n  white-space: nowrap;\n  text-transform: uppercase;\n}\n\n.level-b {\n  background: rgba(0, 160, 80, 0.1);\n  color: #00803A;\n  border: 1px solid rgba(0,160,80,0.2);\n}\n\n.level-i {\n  background: rgba(230, 140, 0, 0.1);\n  color: #8A5200;\n  border: 1px solid rgba(230,140,0,0.2);\n}\n\n.level-a {\n  background: rgba(229, 0, 10, 0.1);\n  color: var(--red);\n  border: 1px solid rgba(229,0,10,0.2);\n}\n\n.tools-footer {\n  background: var(--dark2);\n  color: var(--cream);\n  padding: 20px 40px;\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.tools-footer-label {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 2px;\n  color: var(--red);\n  text-transform: uppercase;\n  white-space: nowrap;\n}\n\n.tools-list {\n  font-family: 'DM Mono', monospace;\n  font-size: 11px;\n  color: rgba(255,255,255,0.4);\n  line-height: 1.6;\n}\n\n/* ─── WHO CAN JOIN ───────────────────────────────── */\n.audience-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n  margin-top: 48px;\n}\n\n.audience-card {\n  background: var(--white);\n  border: 1px solid rgba(0,0,0,0.07);\n  padding: 28px;\n  position: relative;\n  overflow: hidden;\n}\n\n.audience-card::after {\n  content: '';\n  position: absolute;\n  bottom: 0; left: 0; right: 0;\n  height: 2px;\n  background: linear-gradient(90deg, var(--red) 0%, transparent 100%);\n}\n\n.audience-type {\n  font-weight: 700;\n  font-size: 15px;\n  color: var(--dark);\n  margin-bottom: 6px;\n}\n\n.audience-bg {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  color: var(--red);\n  letter-spacing: 1px;\n  margin-bottom: 12px;\n}\n\n.audience-gets {\n  font-size: 13px;\n  color: #555;\n  line-height: 1.65;\n}\n\n.requirements-block {\n  margin-top: 48px;\n  background: var(--dark);\n  color: var(--cream);\n  padding: 40px;\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 32px;\n}\n\n.req-title {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 28px;\n  letter-spacing: 1px;\n  margin-bottom: 20px;\n  grid-column: 1 / -1;\n  color: var(--cream);\n}\n\n.req-item {\n  display: flex;\n  gap: 12px;\n  margin-bottom: 14px;\n}\n\n.req-bullet {\n  color: var(--red);\n  font-family: 'DM Mono', monospace;\n  font-size: 12px;\n  min-width: 14px;\n  margin-top: 2px;\n}\n\n.req-text {\n  font-size: 13px;\n  color: rgba(255,255,255,0.6);\n  line-height: 1.6;\n}\n\n.req-text strong { color: var(--cream); font-weight: 600; }\n\n/* ─── MENTOR SYSTEM ──────────────────────────────── */\n.mentor-timeline {\n  margin-top: 48px;\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  border-left: 2px solid rgba(229,0,10,0.2);\n  margin-left: 20px;\n}\n\n.mentor-item {\n  display: flex;\n  gap: 24px;\n  padding: 0 0 36px 32px;\n  position: relative;\n}\n\n.mentor-item::before {\n  content: '';\n  position: absolute;\n  left: -7px;\n  top: 4px;\n  width: 12px; height: 12px;\n  border-radius: 50%;\n  background: var(--red);\n  border: 2px solid var(--cream);\n  box-shadow: 0 0 0 2px var(--red);\n}\n\n.mentor-freq {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 22px;\n  color: var(--dark);\n  min-width: 100px;\n  line-height: 1.2;\n}\n\n.mentor-detail {}\n\n.mentor-event {\n  font-weight: 600;\n  font-size: 15px;\n  color: var(--dark);\n  margin-bottom: 4px;\n}\n\n.mentor-desc {\n  font-size: 13px;\n  color: #666;\n  line-height: 1.6;\n}\n\n/* ─── REWARDS ────────────────────────────────────── */\n.rewards-split {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 2px;\n  margin-top: 48px;\n  background: rgba(0,0,0,0.06);\n}\n\n.rewards-col {\n  background: var(--white);\n  padding: 36px 32px;\n}\n\n.rewards-col-title {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 24px;\n  letter-spacing: 1px;\n  margin-bottom: 24px;\n  color: var(--dark);\n}\n\n.rewards-col.gold {\n  background: var(--dark);\n  color: var(--cream);\n}\n\n.rewards-col.gold .rewards-col-title { color: #FFDD66; }\n\n.reward-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 11px 0;\n  border-bottom: 1px solid rgba(0,0,0,0.06);\n}\n\n.rewards-col.gold .reward-row {\n  border-bottom-color: rgba(255,255,255,0.07);\n}\n\n.reward-row:last-child { border-bottom: none; }\n\n.reward-check {\n  color: var(--red);\n  font-size: 13px;\n  min-width: 18px;\n}\n\n.rewards-col.gold .reward-check { color: #FFDD66; }\n\n.reward-name {\n  font-size: 13px;\n  color: var(--dark);\n  flex: 1;\n}\n\n.rewards-col.gold .reward-name { color: rgba(255,255,255,0.8); }\n\n.zcp-box {\n  margin-top: 48px;\n  background: rgba(229,0,10,0.05);\n  border: 1px solid rgba(229,0,10,0.15);\n  padding: 32px;\n}\n\n.zcp-title {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 26px;\n  letter-spacing: 1px;\n  color: var(--dark);\n  margin-bottom: 16px;\n}\n\n.zcp-items {\n  display: flex;\n  gap: 24px;\n}\n\n.zcp-item {\n  flex: 1;\n  display: flex;\n  gap: 12px;\n  align-items: flex-start;\n}\n\n.zcp-points {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 32px;\n  color: var(--red);\n  line-height: 1;\n  min-width: 60px;\n}\n\n.zcp-value {\n  font-size: 13px;\n  color: #555;\n  line-height: 1.6;\n  padding-top: 6px;\n}\n\n.zcp-value strong { color: var(--dark); }\n\n/* ─── OWN PROJECT ────────────────────────────────── */\n.own-project-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 2px;\n  margin-top: 48px;\n  background: rgba(0,0,0,0.06);\n}\n\n.op-col {\n  background: var(--white);\n  padding: 32px;\n}\n\n.op-col.dark {\n  background: var(--dark3);\n  color: var(--cream);\n}\n\n.op-col-title {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 22px;\n  letter-spacing: 1px;\n  margin-bottom: 20px;\n}\n\n.op-col.dark .op-col-title { color: #FFDD66; }\n\n.op-row {\n  padding: 12px 0;\n  border-bottom: 1px solid rgba(0,0,0,0.06);\n  font-size: 13px;\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n}\n\n.op-col.dark .op-row { border-bottom-color: rgba(255,255,255,0.06); }\n\n.op-icon { font-size: 12px; margin-top: 1px; }\n.op-row-text { color: #555; line-height: 1.5; }\n.op-col.dark .op-row-text { color: rgba(255,255,255,0.55); }\n\n.steps-flow {\n  margin-top: 48px;\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 0;\n  background: rgba(0,0,0,0.06);\n}\n\n.step-card {\n  background: var(--white);\n  padding: 28px 24px;\n  border-right: 2px solid rgba(0,0,0,0.06);\n  position: relative;\n}\n\n.step-card:last-child { border-right: none; }\n\n.step-arrow {\n  position: absolute;\n  right: -12px;\n  top: 50%;\n  transform: translateY(-50%);\n  font-size: 18px;\n  color: var(--red);\n  z-index: 1;\n  background: var(--white);\n  padding: 2px;\n}\n\n.step-num-big {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 52px;\n  color: rgba(229,0,10,0.1);\n  line-height: 1;\n  margin-bottom: 8px;\n}\n\n.step-title {\n  font-weight: 600;\n  font-size: 14px;\n  color: var(--dark);\n  margin-bottom: 6px;\n}\n\n.step-desc {\n  font-size: 12px;\n  color: #666;\n  line-height: 1.55;\n}\n\n/* ─── CLOSING / CTA ──────────────────────────────── */\n.closing {\n  background: var(--dark);\n  color: var(--cream);\n  padding: 80px 52px;\n  display: flex;\n  align-items: center;\n  gap: 80px;\n  position: relative;\n  overflow: hidden;\n}\n\n.closing::before {\n  content: 'ZHARNYX';\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 200px;\n  color: rgba(255,255,255,0.03);\n  position: absolute;\n  right: -20px;\n  bottom: -40px;\n  pointer-events: none;\n  letter-spacing: 4px;\n}\n\n.closing-left { flex: 1; position: relative; z-index: 1; }\n\n.closing-eyebrow {\n  font-family: 'DM Mono', monospace;\n  font-size: 10px;\n  letter-spacing: 2px;\n  color: var(--red);\n  text-transform: uppercase;\n  margin-bottom: 16px;\n}\n\n.closing-headline {\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 64px;\n  line-height: 0.95;\n  letter-spacing: 1px;\n  margin-bottom: 20px;\n}\n\n.closing-sub {\n  font-size: 15px;\n  color: rgba(255,255,255,0.45);\n  max-width: 400px;\n  line-height: 1.7;\n}\n\n.closing-right {\n  position: relative; z-index: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.contact-item {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.contact-label {\n  font-family: 'DM Mono', monospace;\n  font-size: 9px;\n  letter-spacing: 2px;\n  color: rgba(255,255,255,0.25);\n  text-transform: uppercase;\n}\n\n.contact-value {\n  font-family: 'DM Mono', monospace;\n  font-size: 14px;\n  color: var(--red);\n}\n\n.closing-tagline {\n  border-top: 1px solid rgba(255,255,255,0.06);\n  padding-top: 20px;\n  font-family: 'Bebas Neue', sans-serif;\n  font-size: 18px;\n  letter-spacing: 3px;\n  color: rgba(255,255,255,0.2);\n  text-align: right;\n}\n\n/* ─── PRINT / LAYOUT ─────────────────────────────── */\n@media print {\n  .cover { min-height: 100vh; page-break-after: always; }\n  .section { page-break-inside: avoid; }\n  .track-panels .track-panel { display: block !important; }\n  .tracks-nav { display: none; }\n}\n\n/* ─── ANIMATIONS ─────────────────────────────────── */\n@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(16px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n.cover-headline { animation: fadeIn 0.8s 0.1s ease both; }\n.cover-eyebrow { animation: fadeIn 0.6s ease both; }\n.cover-sub { animation: fadeIn 0.8s 0.25s ease both; }\n.cover-pills { animation: fadeIn 0.8s 0.4s ease both; }\n.cover-stats { animation: fadeIn 0.8s 0.5s ease both; }\n";
const pageBody = "\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  COVER PAGE                                    -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"cover\">\n  <div class=\"cover-grid\"></div>\n  <div class=\"cover-inner\">\n    <header class=\"cover-header\">\n      <div class=\"brand\">ZHAR<span>N</span>YX</div>\n      <div class=\"cover-tag\">Tamil Nadu's Own Technology Academy · 2026</div>\n    </header>\n\n    <div class=\"cover-main\">\n      <div class=\"cover-eyebrow\">Online Internship Program</div>\n      <div class=\"cover-headline\">REAL<br>WORK.<br><em>REAL</em><br>PROOF.</div>\n      <div class=\"cover-sub\">\n        5 technology tracks. 25 real-world problems each. One month of mentor-guided building — from a project that goes straight onto your resume and GitHub.\n      </div>\n      <div class=\"cover-pills\">\n        <span class=\"pill accent\">AI & Machine Learning</span>\n        <span class=\"pill accent\">Cloud</span>\n        <span class=\"pill accent\">Cyber Security</span>\n        <span class=\"pill accent\">Data Analytics</span>\n        <span class=\"pill accent\">DevOps</span>\n        <span class=\"pill\">100% Online</span>\n        <span class=\"pill\">Mentor-Guided</span>\n        <span class=\"pill\">Verified Certificate</span>\n      </div>\n    </div>\n\n    <div class=\"cover-stats\">\n      <div class=\"stat-block\">\n        <div class=\"stat-num\">5</div>\n        <div class=\"stat-label\">Tech Tracks</div>\n      </div>\n      <div class=\"stat-block\">\n        <div class=\"stat-num\">25</div>\n        <div class=\"stat-label\">Projects Per Track</div>\n      </div>\n      <div class=\"stat-block\">\n        <div class=\"stat-num\">4</div>\n        <div class=\"stat-label\">Weeks Duration</div>\n      </div>\n      <div class=\"stat-block\">\n        <div class=\"stat-num\">15–18</div>\n        <div class=\"stat-label\">Hrs / Week</div>\n      </div>\n      <div class=\"stat-block\">\n        <div class=\"stat-num\">₹0</div>\n        <div class=\"stat-label\">Tool Costs</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  ABOUT                                         -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"page\">\n<div class=\"section\">\n  <div class=\"section-label\">About the Program</div>\n  <div class=\"section-title\">WHAT THIS<br>INTERNSHIP IS</div>\n\n  <div class=\"intro-layout\">\n    <div class=\"intro-text\">\n      <p>Zharnyx is building the technology internship model across 5 domains: Artificial Intelligence & Machine Learning, Cloud, Cyber Security, Data Analytics, and DevOps.</p>\n      <p>Each domain has 25 real-world problems — not textbook exercises, not copied lab sheets. Real problems that companies actually face.</p>\n      <p>Every student picks one problem from their chosen domain and builds a real solution from scratch — guided by a Zharnyx mentor — over 4 structured weeks. The student owns the output, documents it properly, and publishes it on GitHub.</p>\n      <p>That project is what goes on their resume.</p>\n    </div>\n\n    <div class=\"differentiators\">\n      <div class=\"diff-item\">\n        <div class=\"diff-num\">01</div>\n        <div>\n          <div class=\"diff-title\">25 Real Problems Per Track</div>\n          <div class=\"diff-text\">Every student picks one that matches their interest and level — from beginner to advanced.</div>\n        </div>\n      </div>\n      <div class=\"diff-item\">\n        <div class=\"diff-num\">02</div>\n        <div>\n          <div class=\"diff-title\">Genuinely Personalised</div>\n          <div class=\"diff-text\">The mentor adapts guidance to the student's background, pace, and goal — not a generic rubric.</div>\n        </div>\n      </div>\n      <div class=\"diff-item\">\n        <div class=\"diff-num\">03</div>\n        <div>\n          <div class=\"diff-title\">Own Project Option</div>\n          <div class=\"diff-text\">Have your own idea? Submit a proposal. If it's scoped correctly, we'll help you build it.</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  4-WEEK STRUCTURE                              -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"section\">\n  <div class=\"section-label\">Program Structure</div>\n  <div class=\"section-title\">THE 4-WEEK<br>FRAMEWORK</div>\n  <div class=\"section-body\">Every student — regardless of track — follows the same 4-week structure. The project changes, the tools change, the mentor adapts. But the rhythm stays consistent. That's what makes the outcome deliverable and verifiable.</div>\n\n  <div class=\"weeks-grid\">\n    <div class=\"week-card\">\n      <div class=\"week-badge\">01</div>\n      <div class=\"week-label\">Week One</div>\n      <div class=\"week-title\">Setup & Project Scoping</div>\n      <div class=\"week-desc\">Student selects their problem from the 25. Mentor holds a 1-hour kickoff call. Student installs tools, reads the problem brief, and writes a 1-page project plan.</div>\n      <div class=\"milestone\">Project plan approved. Environment running. First output demonstrated.</div>\n    </div>\n\n    <div class=\"week-card\">\n      <div class=\"week-badge\">02</div>\n      <div class=\"week-label\">Week Two</div>\n      <div class=\"week-title\">Core Build — Phase 1</div>\n      <div class=\"week-desc\">Student builds the first 50% of the solution. Daily 3-sentence progress log. Mid-week check-in with mentor to clear blockers and adjust scope if needed.</div>\n      <div class=\"milestone\">50% of project functionally complete. Write-up draft started.</div>\n    </div>\n\n    <div class=\"week-card\">\n      <div class=\"week-badge\">03</div>\n      <div class=\"week-label\">Week Three</div>\n      <div class=\"week-title\">Core Build — Phase 2</div>\n      <div class=\"week-desc\">Project is completed. Mentor reviews the interim output and gives written feedback. Student refines and begins formal documentation and GitHub README.</div>\n      <div class=\"milestone\">Project complete. Write-up submitted for mentor review.</div>\n    </div>\n\n    <div class=\"week-card\">\n      <div class=\"week-badge\">04</div>\n      <div class=\"week-label\">Week Four</div>\n      <div class=\"week-title\">Documentation & Final Review</div>\n      <div class=\"week-desc\">Student polishes write-up. Records a 3–5 minute walkthrough video. Pushes all files to GitHub. Final 1-hour mentor walkthrough. Certificate issued within 48 hours.</div>\n      <div class=\"milestone\">GitHub live. Write-up final. Certificate issued within 48 hours.</div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  TRACKS                                        -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"section\">\n  <div class=\"section-label\">The Five Tracks</div>\n  <div class=\"section-title\">PICK YOUR<br>DOMAIN</div>\n  <div class=\"section-body\">Each track contains 25 real-world problems graded from Beginner to Advanced. Click a track to explore the full project list.</div>\n\n  <div class=\"tracks-nav\">\n    <button class=\"track-tab active\" onclick=\"switchTrack(0, this)\">\n      <span class=\"track-icon\">🤖</span>\n      <span class=\"track-name\">AI & ML</span>\n    </button>\n    <button class=\"track-tab\" onclick=\"switchTrack(1, this)\">\n      <span class=\"track-icon\">☁️</span>\n      <span class=\"track-name\">Cloud</span>\n    </button>\n    <button class=\"track-tab\" onclick=\"switchTrack(2, this)\">\n      <span class=\"track-icon\">🔐</span>\n      <span class=\"track-name\">Cyber Security</span>\n    </button>\n    <button class=\"track-tab\" onclick=\"switchTrack(3, this)\">\n      <span class=\"track-icon\">📊</span>\n      <span class=\"track-name\">Data Analytics</span>\n    </button>\n    <button class=\"track-tab\" onclick=\"switchTrack(4, this)\">\n      <span class=\"track-icon\">⚙️</span>\n      <span class=\"track-name\">DevOps</span>\n    </button>\n  </div>\n\n  <div class=\"track-panels\">\n\n    <!-- AI & ML -->\n    <div class=\"track-panel active\">\n      <div class=\"track-header\">\n        <div class=\"track-hero-num\">01</div>\n        <div class=\"track-hero-content\">\n          <div class=\"track-hero-label\">Track One</div>\n          <div class=\"track-hero-title\">ARTIFICIAL INTELLIGENCE & MACHINE LEARNING</div>\n          <div class=\"track-hero-desc\">From regression models to LLM agents — pick your level, build something that works. Beginner problems produce working models with real datasets. Advanced problems produce production-ready systems.</div>\n        </div>\n      </div>\n      <table class=\"projects-table\">\n        <thead>\n          <tr>\n            <th>#</th>\n            <th>Project</th>\n            <th>Tools</th>\n            <th>Level</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td class=\"proj-num\">01</td><td><div class=\"proj-name\">House Price Predictor</div><div class=\"proj-desc\">Train a regression model on real estate data. Deploy with Streamlit UI.</div></td><td class=\"proj-tools\">Python, Scikit-learn, Pandas, Streamlit</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">02</td><td><div class=\"proj-name\">Student Performance Classifier</div><div class=\"proj-desc\">Classify pass/fail outcomes. Compare Logistic Regression vs Decision Tree.</div></td><td class=\"proj-tools\">Python, Scikit-learn, Matplotlib</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">03</td><td><div class=\"proj-name\">Spam Email Detector</div><div class=\"proj-desc\">NLP pipeline with TF-IDF and Naive Bayes. Report precision, recall, F1.</div></td><td class=\"proj-tools\">Python, NLTK, Scikit-learn</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">04</td><td><div class=\"proj-name\">Movie Recommendation Engine</div><div class=\"proj-desc\">Collaborative filtering using cosine similarity on MovieLens dataset.</div></td><td class=\"proj-tools\">Python, Pandas, Surprise library</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">05</td><td><div class=\"proj-name\">Image Classifier (CNN)</div><div class=\"proj-desc\">Train a CNN on CIFAR-10. Document architecture and training curve.</div></td><td class=\"proj-tools\">Python, TensorFlow / Keras</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">06</td><td><div class=\"proj-name\">Customer Churn Predictor</div><div class=\"proj-desc\">Predict telecom churn using Random Forest. Handle class imbalance with SMOTE.</div></td><td class=\"proj-tools\">Python, Scikit-learn, imbalanced-learn</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">07</td><td><div class=\"proj-name\">Sentiment Analysis API</div><div class=\"proj-desc\">Fine-tune BERT on product reviews. Expose as REST API via FastAPI.</div></td><td class=\"proj-tools\">Python, HuggingFace, FastAPI</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">08</td><td><div class=\"proj-name\">Chatbot with Intent Recognition</div><div class=\"proj-desc\">Rule + ML hybrid chatbot. Train an intent classifier. Test 10 conversation flows.</div></td><td class=\"proj-tools\">Python, Rasa / Dialogflow, NLTK</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">09</td><td><div class=\"proj-name\">Time Series Sales Forecaster</div><div class=\"proj-desc\">Forecast monthly sales using ARIMA and LSTM. Compare accuracy with visualisations.</div></td><td class=\"proj-tools\">Python, Statsmodels, TensorFlow, Plotly</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">10</td><td><div class=\"proj-name\">Object Detection System</div><div class=\"proj-desc\">Use YOLOv8 to detect objects. Fine-tune on a custom class. Package as demo.</div></td><td class=\"proj-tools\">Python, YOLOv8, OpenCV</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">11</td><td><div class=\"proj-name\">Credit Risk Scorer</div><div class=\"proj-desc\">Gradient boosting for loan default prediction. Explain features with SHAP.</div></td><td class=\"proj-tools\">Python, XGBoost, SHAP, Pandas</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">12</td><td><div class=\"proj-name\">Resume Parser with NLP</div><div class=\"proj-desc\">Extract name, skills, experience from PDFs using spaCy NER.</div></td><td class=\"proj-tools\">Python, spaCy, PyMuPDF, Flask</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">13</td><td><div class=\"proj-name\">Medical Image Classifier</div><div class=\"proj-desc\">Classify chest X-rays using transfer learning (ResNet50). Document precision, AUC.</div></td><td class=\"proj-tools\">Python, TensorFlow, Keras, scikit-learn</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">14</td><td><div class=\"proj-name\">Real-Time Face Mask Detector</div><div class=\"proj-desc\">MobileNet transfer learning. Demo mask vs no-mask detection in real time.</div></td><td class=\"proj-tools\">Python, OpenCV, TensorFlow / Keras</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">15</td><td><div class=\"proj-name\">News Article Summariser</div><div class=\"proj-desc\">Extractive + abstractive summariser using BERT and T5. Compare on 20 articles.</div></td><td class=\"proj-tools\">Python, HuggingFace, NLTK</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">16</td><td><div class=\"proj-name\">Fraud Transaction Detector</div><div class=\"proj-desc\">Anomaly detection on financial transactions. Isolation Forest + XGBoost ensemble.</div></td><td class=\"proj-tools\">Python, Scikit-learn, XGBoost, SHAP</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">17</td><td><div class=\"proj-name\">LLM Prompt Engineering Pipeline</div><div class=\"proj-desc\">Production-grade prompt pipeline for customer support. Evaluate with RAGAS.</div></td><td class=\"proj-tools\">Python, LangChain, OpenAI / Ollama API</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">18</td><td><div class=\"proj-name\">RAG Document Q&A System</div><div class=\"proj-desc\">Retrieval-Augmented Generation over a set of PDFs. Cited answers.</div></td><td class=\"proj-tools\">Python, LangChain, FAISS, OpenAI / Ollama</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">19</td><td><div class=\"proj-name\">AI Model Explainability Report</div><div class=\"proj-desc\">Apply LIME, SHAP, and Grad-CAM to a black-box model. 10-page report.</div></td><td class=\"proj-tools\">Python, LIME, SHAP, Grad-CAM</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">20</td><td><div class=\"proj-name\">AutoML Pipeline Builder</div><div class=\"proj-desc\">End-to-end AutoML using TPOT or AutoSklearn. Benchmark 5 datasets.</div></td><td class=\"proj-tools\">Python, TPOT / AutoSklearn, Scikit-learn</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">21</td><td><div class=\"proj-name\">Multi-Label Text Classifier</div><div class=\"proj-desc\">Classify research abstracts into multiple topics. Achieve macro-F1 > 0.70.</div></td><td class=\"proj-tools\">Python, HuggingFace, Scikit-learn</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">22</td><td><div class=\"proj-name\">Speech-to-Text Transcription App</div><div class=\"proj-desc\">Real-time transcription using Whisper. Support Tamil + English with timestamps.</div></td><td class=\"proj-tools\">Python, OpenAI Whisper, Gradio</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">23</td><td><div class=\"proj-name\">AI-Powered Hiring Screener</div><div class=\"proj-desc\">LLMs + NLP to screen resumes against job descriptions. Score and rank applicants.</div></td><td class=\"proj-tools\">Python, LangChain, spaCy, Streamlit</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">24</td><td><div class=\"proj-name\">Predictive Maintenance System</div><div class=\"proj-desc\">Predict machine failure 48 hours in advance using LSTM. Compare with RF baseline.</div></td><td class=\"proj-tools\">Python, TensorFlow, Scikit-learn, Pandas</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">25</td><td><div class=\"proj-name\">Custom AI Tutor Agent</div><div class=\"proj-desc\">Subject-specific tutoring agent with memory, feedback loops, and topic tracking.</div></td><td class=\"proj-tools\">Python, LangChain, OpenAI / Ollama, SQLite</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"tools-footer\">\n        <div class=\"tools-footer-label\">All Free Tools</div>\n        <div class=\"tools-list\">Python · Scikit-learn · TensorFlow / Keras · HuggingFace Transformers · LangChain · Ollama · Streamlit · FastAPI · Google Colab (free GPU)</div>\n      </div>\n    </div>\n\n    <!-- CLOUD -->\n    <div class=\"track-panel\">\n      <div class=\"track-header\">\n        <div class=\"track-hero-num\">02</div>\n        <div class=\"track-hero-content\">\n          <div class=\"track-hero-label\">Track Two</div>\n          <div class=\"track-hero-title\">CLOUD</div>\n          <div class=\"track-hero-desc\">25 hands-on cloud projects across AWS, Azure, and GCP — from first EC2 to multi-cloud architecture. Beginner projects run on free-tier accounts at zero cost to students.</div>\n        </div>\n      </div>\n      <table class=\"projects-table\">\n        <thead><tr><th>#</th><th>Project</th><th>Tools</th><th>Level</th></tr></thead>\n        <tbody>\n          <tr><td class=\"proj-num\">01</td><td><div class=\"proj-name\">AWS EC2 Web Deployment</div><div class=\"proj-desc\">Deploy Node.js or Python app on EC2. Configure Security Groups, Elastic IP.</div></td><td class=\"proj-tools\">AWS EC2, SSH, Nginx</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">02</td><td><div class=\"proj-name\">S3 Static Website Hosting</div><div class=\"proj-desc\">Full static website on S3 with custom domain, HTTPS via CloudFront, and logging.</div></td><td class=\"proj-tools\">AWS S3, CloudFront, Route 53</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">03</td><td><div class=\"proj-name\">IAM Audit & Least Privilege</div><div class=\"proj-desc\">Audit a test account. Identify over-permissive roles. Rewrite 5 policies to least privilege.</div></td><td class=\"proj-tools\">AWS IAM, IAM Analyzer, AWS CLI</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">04</td><td><div class=\"proj-name\">Azure VM Deployment</div><div class=\"proj-desc\">Deploy Windows Server VM on Azure. Configure NSGs, RDP, auto-shutdown.</div></td><td class=\"proj-tools\">Azure Portal, Azure VM, NSG</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">05</td><td><div class=\"proj-name\">Google Cloud Storage Setup</div><div class=\"proj-desc\">Create GCS buckets with versioning, lifecycle policies, and access controls.</div></td><td class=\"proj-tools\">GCP Cloud Storage, gsutil, GCP IAM</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">06</td><td><div class=\"proj-name\">Serverless Contact Form</div><div class=\"proj-desc\">API Gateway + Lambda + SES. No servers. Document cost estimate vs EC2 approach.</div></td><td class=\"proj-tools\">AWS Lambda, API Gateway, SES, Python</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">07</td><td><div class=\"proj-name\">Docker Container Deployment</div><div class=\"proj-desc\">Containerise a Python Flask app. Push to DockerHub. Deploy on AWS EC2 or Azure.</div></td><td class=\"proj-tools\">Docker, DockerHub, AWS / Azure</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">08</td><td><div class=\"proj-name\">Multi-Tier VPC Architecture</div><div class=\"proj-desc\">3-tier VPC: public web, private app, private DB layers. Security Groups, NACLs, NAT.</div></td><td class=\"proj-tools\">AWS VPC, Security Groups, NACLs, NAT GW</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">09</td><td><div class=\"proj-name\">CI/CD Pipeline with GitHub Actions</div><div class=\"proj-desc\">Code push → unit test → Docker build → deploy to cloud. Document every stage.</div></td><td class=\"proj-tools\">GitHub Actions, Docker, AWS / Azure</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">10</td><td><div class=\"proj-name\">Kubernetes Cluster Deployment</div><div class=\"proj-desc\">Deploy multi-container app on K8s. Deployments, Services, and Ingress manifests.</div></td><td class=\"proj-tools\">Kubernetes, kubectl, Helm, EKS / Minikube</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">11</td><td><div class=\"proj-name\">Cloud Cost Optimisation Report</div><div class=\"proj-desc\">Analyse AWS cost report. Identify top 5 waste areas. Written report with projected savings.</div></td><td class=\"proj-tools\">AWS Cost Explorer, Trusted Advisor</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">12</td><td><div class=\"proj-name\">Infrastructure as Code with Terraform</div><div class=\"proj-desc\">Provision complete 3-tier environment. State in S3. Modularised code with README.</div></td><td class=\"proj-tools\">Terraform, AWS, S3 backend</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">13</td><td><div class=\"proj-name\">Cloud Monitoring Dashboard</div><div class=\"proj-desc\">CloudWatch dashboards and alarms for EC2, RDS, Lambda. SNS alerts on threshold breach.</div></td><td class=\"proj-tools\">AWS CloudWatch, SNS, CloudTrail</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">14</td><td><div class=\"proj-name\">Azure Kubernetes Service Deploy</div><div class=\"proj-desc\">Microservices app on AKS. HPA auto-scaling. Document rollout and rollback process.</div></td><td class=\"proj-tools\">Azure AKS, kubectl, Helm, Azure ACR</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">15</td><td><div class=\"proj-name\">Serverless Data Pipeline</div><div class=\"proj-desc\">Event-driven ETL: S3 upload → Lambda trigger → transform → store in DynamoDB / RDS.</div></td><td class=\"proj-tools\">AWS Lambda, S3, DynamoDB, Python</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">16</td><td><div class=\"proj-name\">GitOps with ArgoCD</div><div class=\"proj-desc\">Any Git commit to main triggers automatic Kubernetes deployment via ArgoCD.</div></td><td class=\"proj-tools\">ArgoCD, GitHub, Kubernetes, Docker</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">17</td><td><div class=\"proj-name\">Multi-Cloud Failover Architecture</div><div class=\"proj-desc\">Failover across AWS and Azure. Document RPO/RTO. Test with simulated region failure.</div></td><td class=\"proj-tools\">AWS, Azure, Route 53, Traffic Manager</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">18</td><td><div class=\"proj-name\">Cloud Security Hardening Audit</div><div class=\"proj-desc\">Scan with Prowler / ScoutSuite. Remediate top 10 CIS failures. Before/after evidence report.</div></td><td class=\"proj-tools\">Prowler, ScoutSuite, AWS / Azure</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">19</td><td><div class=\"proj-name\">Kubernetes Network Policy Lab</div><div class=\"proj-desc\">Default-deny network policies. Verify pod-level isolation with live tests.</div></td><td class=\"proj-tools\">Kubernetes, NetworkPolicy, kubectl</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">20</td><td><div class=\"proj-name\">Microservices with Service Mesh</div><div class=\"proj-desc\">3-service app with Istio. mTLS, traffic shaping, and circuit breaking.</div></td><td class=\"proj-tools\">Kubernetes, Istio, Helm, Prometheus</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">21</td><td><div class=\"proj-name\">FinOps Dashboard Build</div><div class=\"proj-desc\">Real-time cloud spend dashboard via AWS Cost Explorer API. Visualise by service and team.</div></td><td class=\"proj-tools\">Python, AWS Cost Explorer API, Grafana</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">22</td><td><div class=\"proj-name\">Disaster Recovery Runbook</div><div class=\"proj-desc\">Design and test DR runbook for a 3-tier app. Validated with simulated DR drill.</div></td><td class=\"proj-tools\">AWS Backup, RDS snapshots, Route 53</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">23</td><td><div class=\"proj-name\">Zero Trust Network Design</div><div class=\"proj-desc\">Implement Zero Trust in AWS or Azure across identity, device, app, and data layers.</div></td><td class=\"proj-tools\">AWS VPC, IAM, Azure Entra ID, Conditional Access</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">24</td><td><div class=\"proj-name\">Platform Engineering — Internal Developer Portal</div><div class=\"proj-desc\">Internal developer portal using Backstage. Integrate with GitHub and Kubernetes.</div></td><td class=\"proj-tools\">Backstage, GitHub, Kubernetes, Node.js</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">25</td><td><div class=\"proj-name\">Cloud Native Observability Stack</div><div class=\"proj-desc\">Full observability: Prometheus + Grafana + Loki + Tempo. All 4 golden signals dashboarded.</div></td><td class=\"proj-tools\">Prometheus, Grafana, Loki, Tempo, K8s</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"tools-footer\">\n        <div class=\"tools-footer-label\">All Free / Free Tier</div>\n        <div class=\"tools-list\">AWS Free Tier · Azure Free Account · GCP Free Tier · Terraform (open-source) · Docker · Kubernetes via Minikube · GitHub Actions</div>\n      </div>\n    </div>\n\n    <!-- CYBER SECURITY -->\n    <div class=\"track-panel\">\n      <div class=\"track-header\">\n        <div class=\"track-hero-num\">03</div>\n        <div class=\"track-hero-content\">\n          <div class=\"track-hero-label\">Track Three</div>\n          <div class=\"track-hero-title\">CYBER SECURITY</div>\n          <div class=\"track-hero-desc\">25 hands-on security projects — from network analysis to red team engagements — all in legal, controlled lab environments. VirtualBox VMs, TryHackMe, HackTheBox, or DVWA.</div>\n        </div>\n      </div>\n      <table class=\"projects-table\">\n        <thead><tr><th>#</th><th>Project</th><th>Tools</th><th>Level</th></tr></thead>\n        <tbody>\n          <tr><td class=\"proj-num\">01</td><td><div class=\"proj-name\">Personal Cyber Lab Setup</div><div class=\"proj-desc\">Build a 3-VM isolated lab: Kali Linux, Windows 10, Metasploitable 2.</div></td><td class=\"proj-tools\">VirtualBox, Kali Linux, Metasploitable</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">02</td><td><div class=\"proj-name\">Network Traffic Analysis</div><div class=\"proj-desc\">Capture 30 min of lab traffic. Identify protocols, anomalies, suspicious patterns.</div></td><td class=\"proj-tools\">Wireshark, tcpdump, Zeek</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">03</td><td><div class=\"proj-name\">Web Vulnerability Scan (DVWA)</div><div class=\"proj-desc\">Structured OWASP Top 10 assessment on DVWA. CVSS score and remediation for each finding.</div></td><td class=\"proj-tools\">Burp Suite Community, Nmap, DVWA</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">04</td><td><div class=\"proj-name\">Password Cracking Lab</div><div class=\"proj-desc\">Crack hashes using wordlists and rules. Document cracking times and policy recommendations.</div></td><td class=\"proj-tools\">Hashcat, John the Ripper, CrackStation</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">05</td><td><div class=\"proj-name\">Phishing Investigation Lab</div><div class=\"proj-desc\">Investigate simulated phishing email. Produce timeline, IOC list, and IR report.</div></td><td class=\"proj-tools\">Wireshark, MXToolbox, Splunk Free</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">06</td><td><div class=\"proj-name\">Bash Automation for Security</div><div class=\"proj-desc\">Write 5 bash scripts: log parser, port scanner, login counter, hash checker, file monitor.</div></td><td class=\"proj-tools\">Bash, Linux CLI, grep, awk, sed</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">07</td><td><div class=\"proj-name\">Python Port Scanner</div><div class=\"proj-desc\">Multi-threaded scanner from scratch. Service banner grabbing and CSV report output.</div></td><td class=\"proj-tools\">Python, socket, threading, csv</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">08</td><td><div class=\"proj-name\">Nmap Network Enumeration Report</div><div class=\"proj-desc\">Structured scan of a lab network. All hosts, open ports, service versions, OS fingerprints.</div></td><td class=\"proj-tools\">Nmap, NSE scripts, Zenmap</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">09</td><td><div class=\"proj-name\">Malware Static Analysis</div><div class=\"proj-desc\">Static analysis on 3 safe samples. PE headers, strings, import tables, and IOC report.</div></td><td class=\"proj-tools\">PEStudio, FLOSS, CFF Explorer, VirusTotal</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">10</td><td><div class=\"proj-name\">SQL Injection Exploitation Lab</div><div class=\"proj-desc\">UNION-based, blind boolean, and time-based SQLi on DVWA. Document payloads and remediation.</div></td><td class=\"proj-tools\">Burp Suite, SQLmap, DVWA</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">11</td><td><div class=\"proj-name\">Active Directory Lab (Attack)</div><div class=\"proj-desc\">AD lab with LLMNR poisoning, Pass-the-Hash, Kerberoasting. Document each countermeasure.</div></td><td class=\"proj-tools\">BloodHound, Responder, Mimikatz (lab)</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">12</td><td><div class=\"proj-name\">Splunk SOC Dashboard</div><div class=\"proj-desc\">Ingest sample logs into Splunk. Dashboard detecting 5 attack patterns with logic docs.</div></td><td class=\"proj-tools\">Splunk Free, SPL, security logs</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">13</td><td><div class=\"proj-name\">Memory Forensics Report</div><div class=\"proj-desc\">Analyse Windows memory dump with Volatility 3. Identify malicious process, C2, injected code.</div></td><td class=\"proj-tools\">Volatility 3, PEStudio, Wireshark</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">14</td><td><div class=\"proj-name\">Web App VAPT Report</div><div class=\"proj-desc\">Full VAPT on DVWA or HackTheBox. Written report: scope, findings, CVSS, remediation.</div></td><td class=\"proj-tools\">Burp Suite, Nmap, SQLmap, Metasploit</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">15</td><td><div class=\"proj-name\">Disk Forensics Investigation</div><div class=\"proj-desc\">Analyse disk image with Autopsy. Recover deleted files, USB events, attack timeline.</div></td><td class=\"proj-tools\">Autopsy, FTK Imager, MFT Explorer</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">16</td><td><div class=\"proj-name\">Firewall Rule Audit</div><div class=\"proj-desc\">Audit a firewall rule set. Identify over-permissive, shadowed, and missing controls.</div></td><td class=\"proj-tools\">PFSense, iptables, Cisco Packet Tracer</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">17</td><td><div class=\"proj-name\">Custom IDS Rule Writing</div><div class=\"proj-desc\">Write 10 Suricata / Snort rules. Test each against lab traffic. Document logic.</div></td><td class=\"proj-tools\">Suricata / Snort, Wireshark, Kali</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">18</td><td><div class=\"proj-name\">MITRE ATT&CK Detection Lab</div><div class=\"proj-desc\">Map 5 techniques to ATT&CK. Build Splunk / Sigma rules. Test with Atomic Red Team.</div></td><td class=\"proj-tools\">Atomic Red Team, Sigma, Splunk, MITRE Nav</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">19</td><td><div class=\"proj-name\">AWS IAM Security Audit</div><div class=\"proj-desc\">Audit misconfigured AWS test account. Remediate. CIS AWS Benchmark compliance report.</div></td><td class=\"proj-tools\">AWS Free Tier, Prowler, IAM Analyzer</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">20</td><td><div class=\"proj-name\">Mobile App VAPT</div><div class=\"proj-desc\">Decompile vulnerable Android APK. Static + dynamic analysis. Top 3 OWASP Mobile findings.</div></td><td class=\"proj-tools\">jadx, MobSF, Frida, adb, Burp Suite</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">21</td><td><div class=\"proj-name\">Threat Intelligence IOC Report</div><div class=\"proj-desc\">Collect IOCs from 3 open feeds. Enrich, deduplicate, score. Structured STIX format report.</div></td><td class=\"proj-tools\">MISP, AlienVault OTX, OpenCTI, Python</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">22</td><td><div class=\"proj-name\">Full DFIR Capstone</div><div class=\"proj-desc\">Full forensic investigation: disk image + memory dump + PCAP. 15-page investigation report.</div></td><td class=\"proj-tools\">Autopsy, Volatility 3, Wireshark, Plaso</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">23</td><td><div class=\"proj-name\">Bug Bounty Recon Toolkit</div><div class=\"proj-desc\">Automated recon pipeline: subdomain enum, port scan, directory bust, screenshot.</div></td><td class=\"proj-tools\">Python, Amass, Nmap, ffuf, Aquatone</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">24</td><td><div class=\"proj-name\">Social Engineering Campaign Simulation</div><div class=\"proj-desc\">Phishing simulation using GoPhish against test org. Document click rates and defences.</div></td><td class=\"proj-tools\">GoPhish, Postfix, domain setup</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">25</td><td><div class=\"proj-name\">Red Team Mini Engagement</div><div class=\"proj-desc\">Scoped mini red team: recon, exploitation, post-exploitation, full report.</div></td><td class=\"proj-tools\">Metasploit, BloodHound, CrackMapExec</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"tools-footer\">\n        <div class=\"tools-footer-label\">All Free Tools</div>\n        <div class=\"tools-list\">VirtualBox + Kali Linux + Metasploitable 2 · Wireshark · Nmap · Burp Suite Community · Splunk Free · Volatility 3 · Autopsy · FTK Imager · TryHackMe free account</div>\n      </div>\n    </div>\n\n    <!-- DATA ANALYTICS -->\n    <div class=\"track-panel\">\n      <div class=\"track-header\">\n        <div class=\"track-hero-num\">04</div>\n        <div class=\"track-hero-content\">\n          <div class=\"track-hero-label\">Track Four</div>\n          <div class=\"track-hero-title\">DATA ANALYTICS</div>\n          <div class=\"track-hero-desc\">25 projects from Excel dashboards to real-time data pipelines — the full analyst skill stack. Every project produces a visual output — dashboard, report, or pipeline — that students can demo in any interview.</div>\n        </div>\n      </div>\n      <table class=\"projects-table\">\n        <thead><tr><th>#</th><th>Project</th><th>Tools</th><th>Level</th></tr></thead>\n        <tbody>\n          <tr><td class=\"proj-num\">01</td><td><div class=\"proj-name\">Excel to Insight Dashboard</div><div class=\"proj-desc\">Clean a messy real-world dataset. Build pivot tables and a 5-chart dashboard.</div></td><td class=\"proj-tools\">Excel / Google Sheets</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">02</td><td><div class=\"proj-name\">Python Data Cleaning Pipeline</div><div class=\"proj-desc\">Take raw CSV with 10+ quality issues. Clean, validate, export a structured dataset.</div></td><td class=\"proj-tools\">Python, Pandas, NumPy</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">03</td><td><div class=\"proj-name\">Exploratory Data Analysis (EDA)</div><div class=\"proj-desc\">Full EDA on a public Kaggle dataset. Document distributions, outliers, 10 key insights.</div></td><td class=\"proj-tools\">Python, Pandas, Seaborn, Matplotlib</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">04</td><td><div class=\"proj-name\">COVID-19 Data Visualisation</div><div class=\"proj-desc\">Analyse global dataset. Build 8 visualisations showing trends and country comparisons.</div></td><td class=\"proj-tools\">Python, Plotly, Pandas</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">05</td><td><div class=\"proj-name\">SQL Sales Analysis</div><div class=\"proj-desc\">Write 15 SQL queries against a retail database. Answer business questions on top products.</div></td><td class=\"proj-tools\">PostgreSQL / MySQL, DBeaver</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">06</td><td><div class=\"proj-name\">Power BI Sales Dashboard</div><div class=\"proj-desc\">Power BI dashboard from sales dataset. Slicers, KPI cards, trend charts, and map visuals.</div></td><td class=\"proj-tools\">Power BI Desktop, DAX</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">07</td><td><div class=\"proj-name\">Tableau Public Story</div><div class=\"proj-desc\">Tableau story on a social dataset. Minimum 5 views. Published to Tableau Public.</div></td><td class=\"proj-tools\">Tableau Public</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">08</td><td><div class=\"proj-name\">Web Scraping Pipeline</div><div class=\"proj-desc\">Scrape a public website. Clean data. Store in CSV/SQLite. Schedule with cron.</div></td><td class=\"proj-tools\">Python, BeautifulSoup, Scrapy, SQLite</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">09</td><td><div class=\"proj-name\">Customer Segmentation (K-Means)</div><div class=\"proj-desc\">Segment customers by behaviour. Optimal K with elbow method. Name each segment.</div></td><td class=\"proj-tools\">Python, Scikit-learn, Seaborn, Pandas</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">10</td><td><div class=\"proj-name\">A/B Test Analysis Report</div><div class=\"proj-desc\">Statistical significance testing on A/B dataset. Business recommendation with confidence.</div></td><td class=\"proj-tools\">Python, SciPy, Pandas, Matplotlib</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">11</td><td><div class=\"proj-name\">Google Analytics-Style Dashboard</div><div class=\"proj-desc\">Web analytics dashboard from server logs: sessions, bounce rate, top pages, traffic sources.</div></td><td class=\"proj-tools\">Python, Pandas, Plotly Dash / Streamlit</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">12</td><td><div class=\"proj-name\">Time Series Demand Forecasting</div><div class=\"proj-desc\">Forecast monthly demand using ARIMA and Prophet. Compare models on MAE/RMSE.</div></td><td class=\"proj-tools\">Python, Statsmodels, Prophet, Plotly</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">13</td><td><div class=\"proj-name\">ETL Pipeline Build</div><div class=\"proj-desc\">Extract from CSV/API, transform with Pandas, load to PostgreSQL. Schedule with Airflow.</div></td><td class=\"proj-tools\">Python, Pandas, PostgreSQL, Airflow</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">14</td><td><div class=\"proj-name\">Healthcare Data Analysis</div><div class=\"proj-desc\">Analyse clinical dataset. Identify risk factors for a condition with statistical evidence.</div></td><td class=\"proj-tools\">Python, Pandas, Scipy, Seaborn</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">15</td><td><div class=\"proj-name\">NLP Text Analysis Report</div><div class=\"proj-desc\">Analyse 1,000+ posts. Topic modelling, sentiment trends, keyword frequency. Visualised report.</div></td><td class=\"proj-tools\">Python, NLTK, Gensim, WordCloud</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">16</td><td><div class=\"proj-name\">Real-Time Streaming Dashboard</div><div class=\"proj-desc\">Stream live data via Kafka. Build real-time Grafana or Streamlit dashboard.</div></td><td class=\"proj-tools\">Python, Kafka / API, InfluxDB, Grafana</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">17</td><td><div class=\"proj-name\">Data Warehouse Design</div><div class=\"proj-desc\">Star schema for retail in Snowflake / BigQuery. Write 10 analytical queries. Document ERD.</div></td><td class=\"proj-tools\">Snowflake / BigQuery, SQL, dbt</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">18</td><td><div class=\"proj-name\">Predictive HR Analytics</div><div class=\"proj-desc\">Predict employee attrition. Explain drivers with SHAP. Written HR strategy recommendation.</div></td><td class=\"proj-tools\">Python, Scikit-learn, SHAP, Pandas</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">19</td><td><div class=\"proj-name\">Data Quality Framework</div><div class=\"proj-desc\">Checking framework with rules for completeness, uniqueness, validity. Python with alerts.</div></td><td class=\"proj-tools\">Python, Great Expectations, Pandas</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">20</td><td><div class=\"proj-name\">dbt Analytics Engineering</div><div class=\"proj-desc\">Complete dbt project on retail dataset. Staging, intermediate, mart models, docs, lineage.</div></td><td class=\"proj-tools\">dbt, BigQuery / Snowflake, SQL</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">21</td><td><div class=\"proj-name\">API Data Integration Pipeline</div><div class=\"proj-desc\">Pull from 3 public APIs. Harmonise schemas. Store in database. Build combined dashboard.</div></td><td class=\"proj-tools\">Python, requests, PostgreSQL, Streamlit</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">22</td><td><div class=\"proj-name\">Financial Risk Dashboard</div><div class=\"proj-desc\">Portfolio risk dashboard: VaR, Sharpe ratio, drawdown. Interactive charts on Streamlit.</div></td><td class=\"proj-tools\">Python, Pandas, Plotly, Streamlit</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">23</td><td><div class=\"proj-name\">ML Model Monitoring System</div><div class=\"proj-desc\">Track prediction drift, data drift, and alert on degradation. Visualised dashboard.</div></td><td class=\"proj-tools\">Python, Evidently AI, MLflow, Grafana</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">24</td><td><div class=\"proj-name\">Graph Database Network Analysis</div><div class=\"proj-desc\">Social network or supply chain graph in Neo4j. PageRank and community detection.</div></td><td class=\"proj-tools\">Neo4j, Cypher, Python, NetworkX</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">25</td><td><div class=\"proj-name\">End-to-End Data Product</div><div class=\"proj-desc\">Full stack: ingestion → transformation → model → dashboard → scheduled refresh.</div></td><td class=\"proj-tools\">Python, dbt, Airflow, Streamlit, Postgres</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"tools-footer\">\n        <div class=\"tools-footer-label\">All Free Tools</div>\n        <div class=\"tools-list\">Python · Pandas · NumPy · Power BI Desktop (free) · Tableau Public (free) · Apache Airflow (open-source) · dbt Core (free) · Streamlit · BigQuery / Snowflake free tier</div>\n      </div>\n    </div>\n\n    <!-- DEVOPS -->\n    <div class=\"track-panel\">\n      <div class=\"track-header\">\n        <div class=\"track-hero-num\">05</div>\n        <div class=\"track-hero-content\">\n          <div class=\"track-hero-label\">Track Five</div>\n          <div class=\"track-hero-title\">DEVOPS</div>\n          <div class=\"track-hero-desc\">25 projects from Linux hardening to full GitOps pipelines. Beginner projects run entirely on a student's laptop. Advanced projects use cloud free tiers. Every project produces a working, documented, repeatable system.</div>\n        </div>\n      </div>\n      <table class=\"projects-table\">\n        <thead><tr><th>#</th><th>Project</th><th>Tools</th><th>Level</th></tr></thead>\n        <tbody>\n          <tr><td class=\"proj-num\">01</td><td><div class=\"proj-name\">Linux Server Hardening</div><div class=\"proj-desc\">Harden Ubuntu: disable root SSH, fail2ban, configure UFW, enable automatic updates.</div></td><td class=\"proj-tools\">Ubuntu, UFW, fail2ban, SSH</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">02</td><td><div class=\"proj-name\">Bash Scripts for Admin Tasks</div><div class=\"proj-desc\">Write 5 bash scripts: disk alert, user audit, log archiver, service check, backup automation.</div></td><td class=\"proj-tools\">Bash, cron, Linux CLI</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">03</td><td><div class=\"proj-name\">Git Branching Strategy</div><div class=\"proj-desc\">Implement GitFlow on a sample repo. Write branching, PR, and merge policy document.</div></td><td class=\"proj-tools\">Git, GitHub / GitLab</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">04</td><td><div class=\"proj-name\">Nginx Reverse Proxy Setup</div><div class=\"proj-desc\">Configure Nginx as reverse proxy for 2 backends. SSL with Let's Encrypt. Document and test.</div></td><td class=\"proj-tools\">Nginx, Let's Encrypt, Linux</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">05</td><td><div class=\"proj-name\">Docker First Container</div><div class=\"proj-desc\">Containerise a Python Flask app from scratch. Build, run, and push image to DockerHub.</div></td><td class=\"proj-tools\">Docker, DockerHub, Python Flask</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">06</td><td><div class=\"proj-name\">Basic CI Pipeline (GitHub Actions)</div><div class=\"proj-desc\">GitHub Actions workflow: on push → lint → unit test → build artifact. Document triggers.</div></td><td class=\"proj-tools\">GitHub Actions, Python / Node.js</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">07</td><td><div class=\"proj-name\">VM Provisioning with Vagrant</div><div class=\"proj-desc\">Provision multi-VM environment (web + db) with Vagrant. Automate with shell provisioner.</div></td><td class=\"proj-tools\">Vagrant, VirtualBox, Bash</td><td><span class=\"level-badge level-b\">Beginner</span></td></tr>\n          <tr><td class=\"proj-num\">08</td><td><div class=\"proj-name\">Ansible Playbook — Server Config</div><div class=\"proj-desc\">Configure 3 Linux servers: install packages, create users, deploy web app. Idempotent playbooks.</div></td><td class=\"proj-tools\">Ansible, YAML, Linux</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">09</td><td><div class=\"proj-name\">Docker Compose Multi-Service App</div><div class=\"proj-desc\">3-container app (web + API + DB) with persistent volumes, custom network, health checks.</div></td><td class=\"proj-tools\">Docker Compose, Nginx, PostgreSQL</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">10</td><td><div class=\"proj-name\">CI/CD Pipeline — Full Cycle</div><div class=\"proj-desc\">Code push → test → Docker build → push to registry → deploy to server automatically.</div></td><td class=\"proj-tools\">GitHub Actions, Docker, DockerHub, SSH</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">11</td><td><div class=\"proj-name\">Terraform Infrastructure Build</div><div class=\"proj-desc\">Provision VPC, EC2, and RDS in AWS using Terraform. Variables, outputs, remote state in S3.</div></td><td class=\"proj-tools\">Terraform, AWS, S3 backend</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">12</td><td><div class=\"proj-name\">Kubernetes Pod Deployment</div><div class=\"proj-desc\">Containerised app on Kubernetes. Deployment, Service, ConfigMap manifests. Scale to 3 pods.</div></td><td class=\"proj-tools\">Kubernetes, kubectl, Minikube / EKS</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">13</td><td><div class=\"proj-name\">Prometheus + Grafana Monitoring</div><div class=\"proj-desc\">Instrument a Python app with custom metrics. Build Grafana dashboard with alerts.</div></td><td class=\"proj-tools\">Prometheus, Grafana, Python, Docker</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">14</td><td><div class=\"proj-name\">Log Aggregation with ELK Stack</div><div class=\"proj-desc\">Ingest Nginx logs into ELK. Kibana dashboard showing error trends and traffic patterns.</div></td><td class=\"proj-tools\">ELK Stack, Docker Compose, Nginx</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">15</td><td><div class=\"proj-name\">Secrets Management with Vault</div><div class=\"proj-desc\">Deploy HashiCorp Vault. Store and retrieve secrets from an app. Dynamic secrets for a database.</div></td><td class=\"proj-tools\">HashiCorp Vault, Python, Docker</td><td><span class=\"level-badge level-i\">Intermediate</span></td></tr>\n          <tr><td class=\"proj-num\">16</td><td><div class=\"proj-name\">GitOps with ArgoCD</div><div class=\"proj-desc\">Any push to Git automatically syncs Kubernetes cluster state via ArgoCD.</div></td><td class=\"proj-tools\">ArgoCD, GitHub, Kubernetes, Helm</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">17</td><td><div class=\"proj-name\">Multi-Stage Docker Build</div><div class=\"proj-desc\">Optimise Docker image with multi-stage builds. Reduce size by 60%+. Security scan with Trivy.</div></td><td class=\"proj-tools\">Docker, Trivy, DockerHub</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">18</td><td><div class=\"proj-name\">Kubernetes Helm Chart</div><div class=\"proj-desc\">Package microservices app as Helm chart. Dev/staging/prod values. Deploy across 2 environments.</div></td><td class=\"proj-tools\">Helm, Kubernetes, YAML</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">19</td><td><div class=\"proj-name\">SRE Runbook — Incident Response</div><div class=\"proj-desc\">Full SRE runbook: alert → triage → escalation → RCA → post-mortem template.</div></td><td class=\"proj-tools\">Confluence / Notion, PagerDuty / OpsGenie</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">20</td><td><div class=\"proj-name\">Platform Engineering with Backstage</div><div class=\"proj-desc\">Backstage developer portal with software catalogue, tech radar, and one custom plugin.</div></td><td class=\"proj-tools\">Backstage, GitHub, Node.js</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">21</td><td><div class=\"proj-name\">Service Mesh with Istio</div><div class=\"proj-desc\">Istio on K8s cluster. mTLS, traffic shifting, and circuit breaking across 3 microservices.</div></td><td class=\"proj-tools\">Istio, Kubernetes, Helm, Prometheus</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">22</td><td><div class=\"proj-name\">Cloud Cost Optimisation Pipeline</div><div class=\"proj-desc\">FinOps pipeline: pull AWS cost data, analyse by team, alert on anomalies, visualise in Grafana.</div></td><td class=\"proj-tools\">Python, AWS Cost Explorer API, Grafana</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">23</td><td><div class=\"proj-name\">Zero Downtime Deployment Strategy</div><div class=\"proj-desc\">Implement 3 strategies: blue/green, canary, rolling update. Test on Kubernetes. Compare trade-offs.</div></td><td class=\"proj-tools\">Kubernetes, Argo Rollouts, GitHub Actions</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">24</td><td><div class=\"proj-name\">Chaos Engineering Experiment</div><div class=\"proj-desc\">Controlled chaos: CPU spike, network latency, pod kill. Document system response and recovery.</div></td><td class=\"proj-tools\">Chaos Monkey / Litmus, Kubernetes, Grafana</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n          <tr><td class=\"proj-num\">25</td><td><div class=\"proj-name\">Full DevOps Capstone Pipeline</div><div class=\"proj-desc\">Complete pipeline from scratch: code → CI → Docker → K8s deploy → monitoring → auto-rollback.</div></td><td class=\"proj-tools\">GitHub Actions, Docker, K8s, Prometheus</td><td><span class=\"level-badge level-a\">Advanced</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"tools-footer\">\n        <div class=\"tools-footer-label\">All Free Tools</div>\n        <div class=\"tools-list\">Ubuntu Linux (VirtualBox / WSL2) · Docker Desktop · Docker Compose · Kubernetes via Minikube · Terraform (open-source) · Ansible · GitHub Actions · Prometheus + Grafana · ELK Stack</div>\n      </div>\n    </div>\n\n  </div><!-- /track-panels -->\n</div><!-- /tracks section -->\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  WHO CAN JOIN                                  -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"section\">\n  <div class=\"section-label\">Eligibility</div>\n  <div class=\"section-title\">WHO THIS<br>IS BUILT FOR</div>\n\n  <div class=\"audience-grid\">\n    <div class=\"audience-card\">\n      <div class=\"audience-type\">2nd / 3rd Year Student</div>\n      <div class=\"audience-bg\">CSE · IT · ECE · Basic programming required</div>\n      <div class=\"audience-gets\">Real project, tools exposure, GitHub portfolio, and verified certificate. No prior domain experience needed — the problem bank has beginner levels.</div>\n    </div>\n    <div class=\"audience-card\">\n      <div class=\"audience-type\">Final Year Student</div>\n      <div class=\"audience-bg\">Any degree · Placement preparation</div>\n      <div class=\"audience-gets\">Portfolio project plus interview talking points built from real work. Verified certificate for placement profile.</div>\n    </div>\n    <div class=\"audience-card\">\n      <div class=\"audience-type\">Fresh Graduate</div>\n      <div class=\"audience-bg\">0–12 months after degree completion</div>\n      <div class=\"audience-gets\">Full portfolio project, verified certificate, and placement priority eligibility. Proof of skill before entering the job market.</div>\n    </div>\n    <div class=\"audience-card\">\n      <div class=\"audience-type\">IT Professional (Career Switch)</div>\n      <div class=\"audience-bg\">Working in tech · Pivoting into AI, Cloud, or DevOps</div>\n      <div class=\"audience-gets\">Domain-specific project guided by a mentor from industry. Verified credential for the role you are moving toward.</div>\n    </div>\n  </div>\n\n  <div class=\"requirements-block\">\n    <div class=\"req-title\">What You Need to Participate</div>\n    <div>\n      <div class=\"req-item\"><div class=\"req-bullet\">→</div><div class=\"req-text\"><strong>Laptop with minimum 8GB RAM</strong> — required for virtual environments and local model training</div></div>\n      <div class=\"req-item\"><div class=\"req-bullet\">→</div><div class=\"req-text\"><strong>Stable internet connection</strong> — for sessions, tool downloads, and mentor calls</div></div>\n      <div class=\"req-item\"><div class=\"req-bullet\">→</div><div class=\"req-text\"><strong>15 to 18 hours per week</strong> — this is real work, not passive watching</div></div>\n    </div>\n    <div>\n      <div class=\"req-item\"><div class=\"req-bullet\">→</div><div class=\"req-text\"><strong>Basic programming knowledge recommended</strong> — Python or any language; not mandatory for all tracks</div></div>\n      <div class=\"req-item\"><div class=\"req-bullet\">→</div><div class=\"req-text\"><strong>WhatsApp on phone</strong> — daily communication and progress tracking with your mentor</div></div>\n      <div class=\"req-item\"><div class=\"req-bullet\">→</div><div class=\"req-text\"><strong>No prior domain knowledge required</strong> — the problem bank includes beginner, intermediate, and advanced levels</div></div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  OWN PROJECT + PROCESS                         -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"section\">\n  <div class=\"section-label\">Own Project Option</div>\n  <div class=\"section-title\">HAVE YOUR<br>OWN IDEA?</div>\n  <div class=\"section-body\">If you have a project you have been thinking about — a problem you personally encountered, a system you want to build — you do not have to pick from the 25. Submit a proposal and we review it within 48 hours.</div>\n\n  <div class=\"own-project-grid\">\n    <div class=\"op-col\">\n      <div class=\"op-col-title\">What a Strong Proposal Looks Like</div>\n      <div class=\"op-row\"><div class=\"op-icon\">✓</div><div class=\"op-row-text\">A specific problem it solves — not \"I want to learn hacking\" or \"AI project\"</div></div>\n      <div class=\"op-row\"><div class=\"op-icon\">✓</div><div class=\"op-row-text\">Named tools with a clear technical approach and methodology</div></div>\n      <div class=\"op-row\"><div class=\"op-icon\">✓</div><div class=\"op-row-text\">A clear deliverable that can be seen, tested, or read by an external reviewer</div></div>\n      <div class=\"op-row\"><div class=\"op-icon\">✓</div><div class=\"op-row-text\">Scope that genuinely fits 4 weeks — not a 6-month idea compressed</div></div>\n      <div class=\"op-row\"><div class=\"op-icon\">✓</div><div class=\"op-row-text\">Ethical and legal — works only on approved environments</div></div>\n    </div>\n    <div class=\"op-col dark\">\n      <div class=\"op-col-title\">Own-Project Bonus</div>\n      <div class=\"op-row\"><div class=\"op-icon\" style=\"color:#FFDD66\">★</div><div class=\"op-row-text\">Approved own-project students earn +20 ZCP bonus on top of their base score — the highest bonus category in the program.</div></div>\n      <div class=\"op-row\"><div class=\"op-icon\" style=\"color:rgba(255,255,255,0.3)\">→</div><div class=\"op-row-text\">Review decision within 48 hours: approved as-is, approved with modifications, or redirected to the project bank with reasoning.</div></div>\n      <div class=\"op-row\"><div class=\"op-icon\" style=\"color:rgba(255,255,255,0.3)\">→</div><div class=\"op-row-text\">The mentor adapts guidance to your specific idea — not a generic framework applied over a different project.</div></div>\n    </div>\n  </div>\n\n  <div class=\"steps-flow\">\n    <div class=\"step-card\">\n      <div class=\"step-num-big\">01</div>\n      <div class=\"step-title\">Submit Proposal</div>\n      <div class=\"step-desc\">Fill a short form: project idea, tools planned, expected deliverable, duration fit.</div>\n      <div class=\"step-arrow\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step-num-big\">02</div>\n      <div class=\"step-title\">Technical Review</div>\n      <div class=\"step-desc\">Harish reviews scope fit, legal compliance, and technical feasibility.</div>\n      <div class=\"step-arrow\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step-num-big\">03</div>\n      <div class=\"step-title\">Decision in 48hrs</div>\n      <div class=\"step-desc\">Approved / Approved with modifications / Redirected to the project bank.</div>\n      <div class=\"step-arrow\">›</div>\n    </div>\n    <div class=\"step-card\">\n      <div class=\"step-num-big\">04</div>\n      <div class=\"step-title\">+20 ZCP Bonus</div>\n      <div class=\"step-desc\">Approved own-project students earn a bonus credited at final review.</div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  MENTOR SYSTEM                                 -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"section\">\n  <div class=\"section-label\">Mentorship</div>\n  <div class=\"section-title\">ONE MENTOR.<br>FOUR WEEKS.<br>ZERO GUESSWORK.</div>\n  <div class=\"section-body\">Every student gets one dedicated mentor for the full 4 weeks. The mentor knows the student's project, reviews their work, and is personally responsible for the student finishing — not a help desk, a person.</div>\n\n  <div class=\"mentor-timeline\">\n    <div class=\"mentor-item\">\n      <div class=\"mentor-freq\">Day 1<br>Kickoff</div>\n      <div>\n        <div class=\"mentor-event\">1-Hour Kickoff Call (Google Meet)</div>\n        <div class=\"mentor-desc\">Project plan alignment, tool setup check, and first milestone confirmed. Mentor reads student background before the call and arrives prepared.</div>\n      </div>\n    </div>\n    <div class=\"mentor-item\">\n      <div class=\"mentor-freq\">Daily<br>Log</div>\n      <div>\n        <div class=\"mentor-event\">3-Sentence Progress Check</div>\n        <div class=\"mentor-desc\">Student logs daily progress in shared Google Sheet. Mentor reviews. If a blocker is flagged, response within 24 hours — no student sits stuck for more than a day.</div>\n      </div>\n    </div>\n    <div class=\"mentor-item\">\n      <div class=\"mentor-freq\">Every<br>Friday</div>\n      <div>\n        <div class=\"mentor-event\">Weekly 1-Hour 1-on-1</div>\n        <div class=\"mentor-desc\">Review output, give feedback, set next week's tasks. Mentor depth adapts — more hands-on for struggling students, more challenge for strong ones.</div>\n      </div>\n    </div>\n    <div class=\"mentor-item\">\n      <div class=\"mentor-freq\">End of<br>Week 2</div>\n      <div>\n        <div class=\"mentor-event\">Written Mid-Program Feedback</div>\n        <div class=\"mentor-desc\">Specific, actionable feedback on interim output — not a generic rubric. HOD progress report also sent to faculty coordinator with all students' status.</div>\n      </div>\n    </div>\n    <div class=\"mentor-item\">\n      <div class=\"mentor-freq\">Week 4<br>Final</div>\n      <div>\n        <div class=\"mentor-event\">Final 1-Hour Walkthrough Sign-Off</div>\n        <div class=\"mentor-desc\">Mentor confirms quality before certificate is issued. Project must be on GitHub, write-up must be final, walkthrough video must be recorded. Certificate issued within 48 hours.</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  REWARDS                                       -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"section\">\n  <div class=\"section-label\">What You Earn</div>\n  <div class=\"section-title\">OUTCOMES &<br>REWARDS</div>\n\n  <div class=\"rewards-split\">\n    <div class=\"rewards-col\">\n      <div class=\"rewards-col-title\">Every Student Receives</div>\n      <div class=\"reward-row\"><div class=\"reward-check\">✓</div><div class=\"reward-name\">Zharnyx Internship Certificate — Verified Digital</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">✓</div><div class=\"reward-name\">GitHub Portfolio — 1 Complete, Documented Project</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">✓</div><div class=\"reward-name\">40–70 Zharnyx Credit Points (ZCPs)</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">✓</div><div class=\"reward-name\">Lifetime Zharnyx Alumni Network Access</div></div>\n    </div>\n    <div class=\"rewards-col gold\">\n      <div class=\"rewards-col-title\">Top 3 Performers (Score 85+)</div>\n      <div class=\"reward-row\"><div class=\"reward-check\">★</div><div class=\"reward-name\">All standard rewards — plus everything below</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">★</div><div class=\"reward-name\">LinkedIn + Zharnyx Website Showcase Feature</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">★</div><div class=\"reward-name\">Performance Stipend — ₹1,500 / ₹1,000 / ₹500</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">★</div><div class=\"reward-name\">LinkedIn Recommendation — Written by Sanjai R personally</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">★</div><div class=\"reward-name\">Direct Referral to Zharnyx Hiring Partners</div></div>\n      <div class=\"reward-row\"><div class=\"reward-check\">★</div><div class=\"reward-name\">Up to 91 ZCPs (1.3× bonus multiplier)</div></div>\n    </div>\n  </div>\n\n  <div class=\"zcp-box\">\n    <div class=\"zcp-title\">Zharnyx Credit Points — What They Unlock</div>\n    <div class=\"zcp-items\">\n      <div class=\"zcp-item\">\n        <div class=\"zcp-points\">50</div>\n        <div class=\"zcp-value\"><strong>₹500 off</strong> the Zharnyx Foundation Phase — the Cybersecurity Career Track starting module.</div>\n      </div>\n      <div class=\"zcp-item\">\n        <div class=\"zcp-points\">100</div>\n        <div class=\"zcp-value\"><strong>₹1,000 off</strong> the full Zharnyx 7-Month Career Track package across any specialisation.</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n</div><!-- /page wrapper -->\n\n\n<!-- ═════════════════════════════════════════════ -->\n<!--  CLOSING CTA                                   -->\n<!-- ═════════════════════════════════════════════ -->\n<div class=\"closing\">\n  <div class=\"closing-left\">\n    <div class=\"closing-eyebrow\">Apply Now · Batch 2026</div>\n    <div class=\"closing-headline\">ONE MONTH.<br>REAL WORK.<br>FOREVER ON<br>YOUR PROFILE.</div>\n    <div class=\"closing-sub\">Pick your track. Choose your problem. Build it properly. The project is yours — the mentor is there to make sure you finish it right.</div>\n  </div>\n\n  <div class=\"closing-right\">\n    <div class=\"contact-item\">\n      <div class=\"contact-label\">Website</div>\n      <div class=\"contact-value\">zharnyx.com</div>\n    </div>\n    <div class=\"contact-item\">\n      <div class=\"contact-label\">Email</div>\n      <div class=\"contact-value\">sanjai@zharnyx.com</div>\n    </div>\n    <div class=\"contact-item\">\n      <div class=\"contact-label\">Location</div>\n      <div class=\"contact-value\">Coimbatore & Chennai<br>Tamil Nadu, India</div>\n    </div>\n    <div class=\"contact-item\">\n      <div class=\"contact-label\">Level Key</div>\n      <div style=\"display:flex; gap:8px; margin-top:4px; flex-wrap:wrap;\">\n        <span class=\"level-badge level-b\">Beginner</span>\n        <span class=\"level-badge level-i\">Intermediate</span>\n        <span class=\"level-badge level-a\">Advanced</span>\n      </div>\n    </div>\n    <div class=\"closing-tagline\">\n      Every Week. Every Skill.<br>Every Student — Unregrettable.\n    </div>\n  </div>\n</div>\n\n\n<script>\nfunction switchTrack(idx, btn) {\n  document.querySelectorAll('.track-tab').forEach(t => t.classList.remove('active'));\n  document.querySelectorAll('.track-panel').forEach(p => p.classList.remove('active'));\n  btn.classList.add('active');\n  document.querySelectorAll('.track-panel')[idx].classList.add('active');\n}\n</script>\n\n";

export default function CollegePage({ params }: { params: Promise<{ college: string }> }) {
  const unwrappedParams = use(params);

  useEffect(() => {
    document.title = "Zharnyx — Online Internship Program 2026";
    
    // Assign to window so the inline onclick handlers in the raw HTML can execute
    (window as any).switchTrack = (idx: number, btn: HTMLElement) => {
      document.querySelectorAll('.track-tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.track-panel').forEach(p => p.classList.remove('active'));
      btn.classList.add('active');
      document.querySelectorAll('.track-panel')[idx].classList.add('active');
    };
  }, []);

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: pageStyle }} />
      <div className="bg-red-600 text-white p-2 text-center text-sm font-bold uppercase tracking-widest font-mono fixed top-0 w-full z-[9999]">
        Viewing customized track for {unwrappedParams.college.replace(/-/g, ' ').toUpperCase()}
      </div>
      <div 
        style={{ paddingTop: '36px' }}
        dangerouslySetInnerHTML={{ __html: pageBody }} 
      />
    </>
  );
}
